-- Specialized newsroom agent mesh for fast, source-grounded BuildPulse coverage.
-- Agent rows are service-role only through the existing control-plane RLS/grants.
on conflict(code) do update set name=excluded.name,domain=excluded.domain,autonomy_level=excluded.autonomy_level,description=excluded.description,allowed_actions=excluded.allowed_actions,blocked_actions=excluded.blocked_actions,schedule_hint=excluded.schedule_hint,config=excluded.config,enabled=true,updated_at=now();

select id,'rapid-newsroom','hourly',
case
 when code like 'desk-%' then 'Review newly verified BuildPulse stories for your configured desk since the previous run. Prioritize newest material, breaking significance, source provenance, useful detail and available source imagery. Deduplicate aggressively. Produce a source-grounded editorial proposal only; never invent missing facts or bypass publication review.'
 when code='breaking-news' then 'Rank newly verified stories across all desks by freshness, significance and corroboration. Flag only evidence-backed breaking candidates and preserve source URLs and timestamps.'
 when code='source-freshness' then 'Inspect enabled BuildPulse sources for stale fetches, repeated failures and abnormal latency. Produce bounded operational flags and recovery recommendations without changing credentials.'
 when code='news-dedupe' then 'Inspect recent incoming stories for duplicate or near-duplicate coverage. Preserve every source relationship and recommend canonical clusters; do not delete published evidence.'
 when code='provenance-check' then 'Inspect recent publication candidates for canonical source URL, source identity, timestamps and verification evidence. Fail closed on missing provenance.'
 when code='media-enrichment' then 'Inspect recent verified stories missing imagery or media metadata. Use only source-provided or rights-safe media references, preserve attribution and propose useful alt text.'
 when code='seo-news' then 'Prepare factual metadata, structured-data suggestions and internal links for newly verified stories using only facts already present in verified story evidence.'
 when code='publication-health' then 'Inspect desk freshness, empty desks, route health, sitemap coverage and publication latency. Flag stale or broken surfaces with concrete evidence.'
end,now()
from public.buildpulse_agents
where code like 'desk-%' or code in ('breaking-news','source-freshness','news-dedupe','provenance-check','media-enrichment','seo-news','publication-health')
on conflict(agent_id,name) do update set enabled=true,input_template=excluded.input_template,next_run_at=least(public.buildpulse_agent_schedules.next_run_at,now()),updated_at=now();
